// Validates design/tokens.json and writes the generated theme files for Mobile and Web.
// Usage: node --experimental-strip-types design/build-tokens.ts [--check]
//   --check  writes nothing; fails if a rule is broken or a generated file is out of date.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

type ColorSet = Record<string, string>;
type ContrastPair = { foreground: string; background: string; minimum: number };
type TypeLevel = { size: number; lineHeight: number; weight: string; family: "brand" | "system" };
type Tokens = {
  version: number;
  color: { light: ColorSet; dark: ColorSet };
  contrastPairs: ContrastPair[];
  typography: {
    brandFamily: string;
    brandWeights: { semibold: string; bold: string };
    scale: Record<string, TypeLevel>;
  };
  spacing: Record<string, number>;
  radius: Record<string, number>;
  size: { touchTarget: number };
};

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(ROOT, "design", "tokens.json");
const MOBILE_OUT = join(ROOT, "mobile", "src", "theme", "tokens.generated.ts");
const WEB_OUT = join(ROOT, "web", "src", "styles", "tokens.generated.css");
// Plain JSON for app.config.ts: Expo's config loader cannot import TypeScript modules.
const MOBILE_CONFIG_OUT = join(ROOT, "mobile", "src", "theme", "tokens.generated.json");
// Colors for the Web manifest (feature 007), which cannot read CSS variables.
const WEB_JSON_OUT = join(ROOT, "web", "src", "styles", "tokens.generated.json");
const HEADER = "Generated by design/build-tokens.ts from design/tokens.json. Do not edit by hand.";
const HEX = /^#[0-9A-F]{6}$/;
const MODES = ["light", "dark"] as const;

function channel(value: number): number {
  const c = value / 255;
  return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

function luminance(hex: string): number {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
}

/** WCAG 2.x contrast ratio. */
export function contrast(a: string, b: string): number {
  const [high, low] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (high + 0.05) / (low + 0.05);
}

function validate(tokens: Tokens): string[] {
  const errors: string[] = [];
  const lightRoles = Object.keys(tokens.color.light).sort();
  const darkRoles = Object.keys(tokens.color.dark).sort();
  for (const role of lightRoles) {
    if (!darkRoles.includes(role)) errors.push(`role: "${role}" is missing in dark`);
  }
  for (const role of darkRoles) {
    if (!lightRoles.includes(role)) errors.push(`role: "${role}" is missing in light`);
  }
  for (const mode of MODES) {
    for (const [role, value] of Object.entries(tokens.color[mode])) {
      if (!HEX.test(value)) errors.push(`format: ${role} (${mode}) is "${value}", expected #RRGGBB`);
    }
  }
  for (const pair of tokens.contrastPairs) {
    for (const mode of MODES) {
      const colors = tokens.color[mode];
      const fg = colors[pair.foreground];
      const bg = colors[pair.background];
      if (!fg || !bg) {
        errors.push(`pair: ${pair.foreground} on ${pair.background} uses an unknown role`);
        continue;
      }
      const ratio = contrast(fg, bg);
      if (ratio < pair.minimum) {
        errors.push(
          `contrast: ${pair.foreground} on ${pair.background} (${mode}) is ` +
            `${ratio.toFixed(2)}:1, minimum ${pair.minimum}:1`,
        );
      }
    }
  }
  return errors;
}

function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
}

function mobileFile(tokens: Tokens): string {
  const { version: _version, ...data } = tokens;
  return [
    `// ${HEADER}`,
    `export const tokens = ${JSON.stringify(data, null, 2)} as const;`,
    "",
    "export type ColorRole = keyof typeof tokens.color.light;",
    "",
  ].join("\n");
}

function webFile(tokens: Tokens): string {
  const colorVars = (set: ColorSet, indent: string) =>
    Object.entries(set).map(([role, value]) => `${indent}--color-${kebab(role)}: ${value};`);
  const brand =
    tokens.typography.brandFamily === "System"
      ? "system-ui, sans-serif"
      : `"${tokens.typography.brandFamily}", system-ui, sans-serif`;
  const shared = [
    ...Object.entries(tokens.spacing).map(([name, value]) => `  --space-${name}: ${value}px;`),
    ...Object.entries(tokens.radius).map(([name, value]) => `  --radius-${name}: ${value}px;`),
    `  --size-touch-target: ${tokens.size.touchTarget}px;`,
    `  --font-brand: ${brand};`,
    "  --font-system: system-ui, sans-serif;",
  ];
  return [
    `/* ${HEADER} */`,
    ":root {",
    ...colorVars(tokens.color.light, "  "),
    ...shared,
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    '  :root:not([data-theme="light"]) {',
    ...colorVars(tokens.color.dark, "    "),
    "  }",
    "}",
    "",
    ':root[data-theme="dark"] {',
    ...colorVars(tokens.color.dark, "  "),
    "}",
    "",
  ].join("\n");
}

function main(): number {
  const check = process.argv.includes("--check");
  const tokens = JSON.parse(readFileSync(SOURCE, "utf8")) as Tokens;
  const errors = validate(tokens);
  if (errors.length > 0) {
    for (const error of errors) console.error(error);
    return 1;
  }
  const outputs: [string, string][] = [
    [MOBILE_OUT, mobileFile(tokens)],
    [MOBILE_CONFIG_OUT, `${JSON.stringify({ color: tokens.color }, null, 2)}
`],
    [WEB_OUT, webFile(tokens)],
    [WEB_JSON_OUT, `${JSON.stringify({ color: tokens.color }, null, 2)}
`],
  ];
  let stale = 0;
  for (const [file, content] of outputs) {
    const name = relative(ROOT, file).replaceAll("\\", "/");
    if (check) {
      const current = existsSync(file) ? readFileSync(file, "utf8").replace(/\r\n/g, "\n") : "";
      if (current !== content) {
        console.error(`stale: ${name} does not match design/tokens.json; run npm run tokens`);
        stale++;
      }
    } else {
      writeFileSync(file, content);
      console.log(`wrote ${name}`);
    }
  }
  if (check && stale === 0) console.log("tokens: ok");
  return stale > 0 ? 1 : 0;
}

process.exitCode = main();
